base='../persistent/stock_data'; cutoff=pd.Timestamp('2026-12-30')
px={}; vol={}
for a in assets:
 p=f'{base}/{a}.csv'
 if os.path.exists(p):
  d=pd.read_csv(p); d.date=pd.to_datetime(d.date); d=d.sort_values('date').set_index('date').loc[:cutoff]
  px[a]=d.close; vol[a]=d.volume.replace(0,np.nan)
P=pd.DataFrame(px); V=pd.DataFrame(vol).reindex(P.index); R=P.pct_change()
