p=pd.DataFrame(D).ffill().loc[:'2028-03-22']; r=p.pct_change()
down=r.where(r<0,0).rolling(30).std()
f=(p.pct_change(30)/(down*np.sqrt(30)+1e-8)).shift(1)
print('sample_end',p.index.max().date(),'dates',len(p),'assets',p.shape[1])
for h in [1,5,10]:
 x=p.shift(-h).div(p)-1; vals=[]; ns=[]; ds=[]
 for dt in f.index:
