for nm,(a,b) in {'2020-22':('2020','2022-12-31'),'2023-24':('2023','2024-12-31'),'2025-26':('2025','2026-12-31'),'2027-28':('2027','2028-03-22')}.items():
 vals=[]
 for dt in f.loc[a:b].index:
