import numpy as np,pandas as pd
from alphacrafter.sim.utils import get_index_daily_data,get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def fetch(s):
    for f in (get_index_daily_data,get_stock_daily_data):
        try:
            d=f(s,days=4000)
            if d is not None and len(d): return d
        except Exception: pass
S={}
for s in U:
    d=fetch(s)
    if d is None: continue
    d=d.copy(); d.date=pd.to_datetime(d.date); d=d.set_index('date').sort_index()
    c=pd.to_numeric(d.close,errors='coerce'); r=c.pct_change()
    # Quality trend: medium return penalized by recent downside variation and unstable volatility.
    dv=r.where(r<0,0.0).rolling(30,min_periods=20).std()
    tv=r.rolling(30,min_periods=20).std()
    vp=(r.rolling(10,min_periods=8).std()/(tv+1e-8)).clip(0.25,4)
    sig=(c.pct_change(20))/(0.01+dv*np.sqrt(30)) / (1+0.35*(vp-1).abs())
    S[s]=pd.DataFrame({'sig':sig,'f1':c.shift(-1)/c-1,'f5':c.shift(-5)/c-1,'f10':c.shift(-10)/c-1,'f20':c.shift(-20)/c-1})
D=sorted(set().union(*[x.index for x in S.values()])); rows=[]
for dt in D:
    a=[]
    for s,x in S.items():
        if dt in x.index and np.isfinite(x.loc[dt]).all(): a.append((s,*x.loc[dt].values))
    if len(a)>=8:
        z=pd.DataFrame(a,columns=['s','sig','f1','f5','f10','f20'])
        for h in [1,5,10,20]:
            q=z.dropna(subset=['sig',f'f{h}'])
            if len(q)>=8: rows.append((dt,h,q.sig.rank().corr(q[f'f{h}'].rank()),len(q)))
q=pd.DataFrame(rows,columns=['date','h','ic','n'])
for h in [1,5,10,20]:
 x=q[q.h==h].copy(); m=x.ic.mean(); sd=x.ic.std(ddof=1)
 print(f'{h}d dates={len(x)} avg_n={x.n.mean():.2f} coverage={x.n.mean()/15:.4f} IC={m:.6f} ICIR={m/sd*np.sqrt(252):.4f} hit={(x.ic>0).mean():.4f} turnover_proxy={x.ic.diff().abs().mean():.6f}')
 for a,b in [('2020','2022-12-31'),('2023','2024-12-31'),('2025','2026-12-31'),('2027','2028-12-31'),('2029','2029-12-31')]:
  y=x[(x.date.astype(str)>=a)&(x.date.astype(str)<=b)].ic; print('regime',a,len(y),f'{y.mean():.6f}')

